  "research.cmd.btn_promote_active": { fa: "ارتقا به → ACTIVE", de: "Befördern → ACTIVE", es: "Promover → ACTIVE", ar: "ترقية إلى → ACTIVE" },
  "research.cmd.promo_note": { fa: "ارتقا نیازمند شناسه بازیگر صریح است (در تبار اعتبارسنجی ثبت می‌شود). پرش‌های غیرقانونی چرخه حیات را ماشین حالت ثبت رد می‌کند — تصمیم با بک‌اند است، رابط فقط درخواست می‌دهد.", de: "Die Beförderung erfordert eine ausdrückliche Actor-ID (wird in der Validierungslinie erfasst). Illegale Lebenszyklus-Sprünge weigert die Registry-Statusmaschine — das Backend entscheidet, die UI fragt nur.", es: "La promoción requiere un identificador de actor explícito (registrado en el linaje de validación). Saltos de ciclo de vida ilegales los rechaza la máquina de estados del registro — el backend decide, la UI solo pregunta.", ar: "تتطلب الترقية معرّف فاعل صريحًا (مسجل في سلالة التحقق). قفزات دورة الحياة غير المشروعة ترفضها آلة حالة السجل — الخادم يقرر، والواجهة تطلب فقط." },
  "research.cmd.actor": { fa: "بازیگر", de: "Akteur", es: "actor", ar: "الفاعل" },
  "research.cmd.confirm_title": { fa: "تأیید: {s}", de: "Bestätigen: {s}", es: "Confirmar: {s}", ar: "تأكيد: {s}" },
  "research.cmd.send": { fa: "ارسال فرمان", de: "Befehl senden", es: "Enviar comando", ar: "إرسال الأمر" },
  "research.cmd.runs_pre": { fa: "این ", de: "Dies führt ", es: "Esto ejecuta ", ar: "يشغّل هذا " },
  "research.cmd.runs_post": { fa: " را روی بک‌اند زنده اجرا می‌کند. دفتر موتور فقط‌افزودنی است؛ فرمان می‌تواند ردیف‌های مشتق اضافه کند اما هرگز شواهد تغییرناپذیر را بازنویسی نمی‌کند.", de: " auf dem Live-Backend aus. Das Engine-Ledger ist append-only; der Befehl darf abgeleitete Zeilen hinzufügen, aber niemals unveränderliche Evidenz umschreiben.", es: " en el backend en vivo. El libro mayor del motor es de solo agregación; el comando puede añadir filas derivadas pero nunca reescribir evidencia inmutable.", ar: " على الخادم الحي. سجل المحرك للإضافة فقط؛ يمكن للأمر إضافة صفوف مشتقة لكنه لا يعيد كتابة الأدلة غير القابلة للتغيير أبدًا." },
  "research.cmd.select_first": { fa: "اول یک ردیف استراتژی انتخاب کنید (بک‌اند strategy_id را لازم دارد).", de: "zuerst eine Strategiezeile auswählen (das Backend verlangt strategy_id).", es: "primero seleccione una fila de estrategia (el backend requiere strategy_id).", ar: "حدّد صف استراتيجية أولًا (يتطلب الخادم strategy_id)." },
  "research.cmd.promote_title": { fa: "تأیید ارتقا → {s}", de: "Beförderung bestätigen → {s}", es: "Confirmar promoción → {s}", ar: "تأكيد الترقية → {s}" },
