  "research.cmd.strategy_pre": { fa: "استراتژی ", de: "Strategie ", es: "estrategia ", ar: "الاستراتيجية " },
  "research.cmd.actor_backend": { fa: "بازیگر (لازم برای بک‌اند)", de: "Akteur (vom Backend erforderlich)", es: "actor (requerido por el backend)", ar: "الفاعل (يتطلبه الخادم)" },
  "research.cmd.active_note": { fa: "ACTIVE یعنی اختیار ارسال واقعی در حالت LIVE. ثبت، استراتژی‌های بدون اعتبارسنجی یا ردشده را صرف این کلیک نمی‌پذیرد.", de: "ACTIVE bedeutet echte Dispatch-Berechtigung im LIVE-Modus. Die Registry lehnt unvalidierte oder abgelehnte Strategien unabhängig von diesem Klick ab.", es: "ACTIVE significa autoridad real de despacho en modo LIVE. El registro rechaza estrategias no validadas o rechazadas independientemente de este clic.", ar: "يعني ACTIVE صلاحية إرسال حقيقية في وضع LIVE. يرفض السجل الاستراتيجيات غير المُتحقق منها أو المرفوضة بغض النظر عن هذا النقر." },

